# -*- coding: utf-8 -*-
"""Contenu du parcours 4e."""
from donnees_communes import IMAGE_LIGNES_BITS

T1 = "Thème 1 « Les objets et les systèmes techniques : leurs usages et leurs interactions à découvrir et analyser »"
T2 = "Thème 2 « Structure, fonctionnement, comportement : des objets et des systèmes techniques à comprendre »"
T3 = "Thème 3 « Création, conception, réalisation, innovations : des objets à concevoir et à réaliser »"

_IMG = ",\n".join('    "%s"' % l for l in IMAGE_LIGNES_BITS)

CODE_SATELLITE = """// Satellite simulé : envoie l'image 8 x 8 ligne par ligne (4e)
radio.setGroup(12)   // numéro de groupe propre à l'équipe (0 à 255)
let image = [
%s
]
// Bouton A : envoyer les 8 lignes, une par paquet
input.onButtonPressed(Button.A, function () {
    for (let n = 0; n < 8; n++) {
        radio.sendString("" + n + ":" + image[n])   // paquet = numéro + ":" + 16 bits
        basic.showNumber(n)
        basic.pause(200)
    }
    basic.showIcon(IconNames.Yes)
})""" % _IMG

CODE_STATION = """// Station au sol : reçoit les lignes et repère les paquets manquants (4e)
radio.setGroup(12)   // même groupe que le satellite
let recues = ["", "", "", "", "", "", "", ""]

radio.onReceivedString(function (message) {
    if (message.charAt(1) == ":") {
        let n = parseInt(message.charAt(0))
        recues[n] = message.substr(2, 16)
        serial.writeLine(message)
    }
})

// Bouton B : bilan de réception
input.onButtonPressed(Button.B, function () {
    let manquants = 0
    for (let n = 0; n < 8; n++) {
        if (recues[n] == "") {
            manquants = manquants + 1
            serial.writeLine("Paquet manquant : " + n)
        }
    }
    basic.showNumber(8 - manquants)
})"""

CODE_PERTES = """// À ajouter dans le programme du satellite pour simuler des pertes :
// remplacer la ligne radio.sendString(...) par :
        if (randint(1, 5) == 1) {
            basic.showIcon(IconNames.No)        // paquet « perdu » (1 chance sur 5)
        } else {
            radio.sendString("" + n + ":" + image[n])
        }"""

CODE_RETRANSMISSION = """// Station au sol — bouton A : demander les paquets manquants
input.onButtonPressed(Button.A, function () {
    for (let n = 0; n < 8; n++) {
        if (recues[n] == "") {
            radio.sendString("R" + n)
            basic.pause(200)
        }
    }
})

// Satellite — renvoyer une ligne quand la station la demande
radio.onReceivedString(function (message) {
    if (message.charAt(0) == "R") {
        let n = parseInt(message.charAt(1))
        radio.sendString("" + n + ":" + image[n])
    }
})"""

